import re
def plain(h): return re.sub(r'<[^>]+>','',re.sub(r'<rt>[^<]*</rt>','',h or ''))
def apply(packs,report=False):
    miss=[]
    for p in packs:
        if p['id'] not in C: continue
        kw=''.join(re.sub(r'<rt>[^<]*</rt>','',l['html']) for l in p['lessons'])
        kws=set(re.findall(r"<span class='kw'>([^<]*)</span>",kw))
        txt=plain(kw)
        for a in re.findall(r'\[\[([^\]]+)\]\]',C[p['id']]):
            if a not in kws and a not in txt: miss.append((p['id'],a))
        cl=[c for c in p.get('cloze',[]) if c.get('title')!=TITLE]
        cl.append(dict(title=TITLE,text=C[p['id']]))
        p['cloze']=cl
    if report and miss: print('note_cloze missing:',miss)
    return miss
